// Mendelian monohybrid cross: Aa x Aa -> F2 ratio.
// trait: Hypertension (SHR)
var dom='A', rec='a';
var gametes=[dom,rec], counts={};
gametes.forEach(function(g1){gametes.forEach(function(g2){
  var geno=[g1,g2].sort().join('');
  var pheno=(geno.indexOf('A')>=0)?'dominant':'recessive';
  counts[pheno]=(counts[pheno]||0)+1;});});
console.log('F2 dominant: '+counts.dominant+'/4, recessive: '+counts.recessive+'/4');
console.log('classic 3:1 Mendelian ratio confirmed');

